import { act, cleanup, fireEvent, render, screen, waitFor } from "@testing-library/react";
import { useState } from "react";
import { afterEach, beforeEach, expect, it, vi, type MockInstance } from "vitest";
import { RadioOutputPlayer } from "./RadioOutputPlayer";
import { RadioMonitorProvider, useRadioMonitor } from "./RadioMonitor";

// gaulatti/alcantara#287: the listener audio belongs to the persistent layout, so it keeps playing
// while the operator moves between console pages.

let grants = 0;
let transport: MockInstance<typeof fetch>;
const ticketFor = (programId: string) => async () =>
  new Response(
    JSON.stringify({
      streamPath: `/radio/${encodeURIComponent(programId)}/monitor-audio?ticket=grant-${++grants}`,
      expiresInMs: 600000,
    }),
    { status: 201 },
  );

beforeEach(() => {
  grants = 0;
  vi.spyOn(HTMLMediaElement.prototype, "play").mockResolvedValue(undefined);
  vi.spyOn(HTMLMediaElement.prototype, "pause").mockImplementation(() => {});
  vi.spyOn(HTMLMediaElement.prototype, "load").mockImplementation(() => {});
  transport = vi.spyOn(globalThis, "fetch").mockImplementation(async (input) => {
    const programId = decodeURIComponent(String(input).split("/radio/")[1].split("/")[0]);
    return ticketFor(programId)();
  });
});
afterEach(() => {
  cleanup();
  vi.restoreAllMocks();
});

/** Two console pages under one persistent provider: one shows the player, one does not. */
function Console({ programId = "station" }: { programId?: string }) {
  const [page, setPage] = useState<"control" | "songs">("control");
  return (
    <RadioMonitorProvider programId={programId}>
      <button onClick={() => setPage(page === "control" ? "songs" : "control")}>Go {page === "control" ? "songs" : "control"}</button>
      {page === "control" ? <RadioOutputPlayer programId={programId} /> : <p>Songs page</p>}
    </RadioMonitorProvider>
  );
}
const audios = () => document.querySelectorAll("audio");

it("keeps one audio element, owned by the provider, and playing across pages", async () => {
  render(<Console />);
  await waitFor(() => expect(screen.getByRole("button", { name: "Listen" })).toBeEnabled());
  expect(audios()).toHaveLength(1);
  const audio = audios()[0];
  fireEvent.click(screen.getByRole("button", { name: "Listen" }));
  await waitFor(() => expect(screen.getByRole("status")).toHaveTextContent("Listening to broadcast"));
  const source = audio.getAttribute("src");
  expect(source).toContain("grant-1");
  vi.mocked(HTMLMediaElement.prototype.pause).mockClear();

  fireEvent.click(screen.getByRole("button", { name: "Go songs" }));
  expect(screen.getByText("Songs page")).toBeInTheDocument();
  expect(audios()[0]).toBe(audio);
  expect(audio.isConnected).toBe(true);
  expect(audio.getAttribute("src")).toBe(source);
  expect(HTMLMediaElement.prototype.pause).not.toHaveBeenCalled();
  expect(HTMLMediaElement.prototype.load).not.toHaveBeenCalled();

  fireEvent.click(screen.getByRole("button", { name: "Go control" }));
  expect(screen.getByRole("status")).toHaveTextContent("Listening to broadcast");
  expect(screen.getByRole("button", { name: "Stop listening" })).toBeInTheDocument();
  expect(audios()).toHaveLength(1);
  expect(audios()[0]).toBe(audio);
  expect(transport).toHaveBeenCalledTimes(1);
});

it("asks for a monitor grant only while a player is on screen", async () => {
  render(<Console />);
  await waitFor(() => expect(transport).toHaveBeenCalledTimes(1));
  fireEvent.click(screen.getByRole("button", { name: "Go songs" }));
  await act(async () => {});
  fireEvent.click(screen.getByRole("button", { name: "Go control" }));
  await waitFor(() => expect(transport).toHaveBeenCalledTimes(2));

  cleanup();
  transport.mockClear();
  render(
    <RadioMonitorProvider programId="station">
      <p>No player here</p>
    </RadioMonitorProvider>,
  );
  await act(async () => {});
  expect(transport).not.toHaveBeenCalled();
});

it("does not renew the grant for audio that is already playing when the player leaves", async () => {
  render(<Console />);
  await waitFor(() => expect(screen.getByRole("button", { name: "Listen" })).toBeEnabled());
  fireEvent.click(screen.getByRole("button", { name: "Listen" }));
  await waitFor(() => expect(screen.getByRole("status")).toHaveTextContent("Listening to broadcast"));
  fireEvent.click(screen.getByRole("button", { name: "Go songs" }));
  await act(async () => {});
  expect(transport).toHaveBeenCalledTimes(1);
});

it("stops the stream when the program changes, and prepares the new program's grant", async () => {
  const { rerender } = render(<Console programId="station" />);
  await waitFor(() => expect(screen.getByRole("button", { name: "Listen" })).toBeEnabled());
  fireEvent.click(screen.getByRole("button", { name: "Listen" }));
  await waitFor(() => expect(screen.getByRole("status")).toHaveTextContent("Listening to broadcast"));
  const audio = audios()[0];
  rerender(<Console programId="other" />);
  expect(audios()[0]).toBe(audio);
  expect(audio).not.toHaveAttribute("src");
  expect(screen.getByRole("status")).not.toHaveTextContent("Listening");
  await waitFor(() => expect(screen.getByRole("button", { name: "Listen" })).toBeEnabled());
  fireEvent.click(screen.getByRole("button", { name: "Listen" }));
  expect(audio.getAttribute("src")).toContain("/radio/other/monitor-audio");
  expect(audios()).toHaveLength(1);
});

it("stops the audio when the persistent layout goes away, as on sign-out", async () => {
  const view = render(<Console />);
  await waitFor(() => expect(screen.getByRole("button", { name: "Listen" })).toBeEnabled());
  fireEvent.click(screen.getByRole("button", { name: "Listen" }));
  await waitFor(() => expect(screen.getByRole("status")).toHaveTextContent("Listening to broadcast"));
  const audio = audios()[0];
  view.unmount();
  expect(HTMLMediaElement.prototype.pause).toHaveBeenCalled();
  expect(audio).not.toHaveAttribute("src");
});

it("lets anything under the provider stop the stream, and reports the shared state", async () => {
  function Probe() {
    const monitor = useRadioMonitor()!;
    return (
      <>
        <output aria-label="state">{monitor.state}</output>
        <button onClick={monitor.stop}>Stop from outside</button>
      </>
    );
  }
  render(
    <RadioMonitorProvider programId="station">
      <Probe />
      <RadioOutputPlayer programId="station" />
    </RadioMonitorProvider>,
  );
  await waitFor(() => expect(screen.getByRole("button", { name: "Listen" })).toBeEnabled());
  fireEvent.click(screen.getByRole("button", { name: "Listen" }));
  await waitFor(() => expect(screen.getByLabelText("state")).toHaveTextContent("playing"));
  fireEvent.click(screen.getByRole("button", { name: "Stop from outside" }));
  expect(screen.getByLabelText("state")).toHaveTextContent("stopped");
  expect(audios()[0]).not.toHaveAttribute("src");
});

it("has no shared monitor outside the layout, and a fixture URL keeps its own audio element", async () => {
  function Outside() {
    return <output aria-label="monitor">{String(useRadioMonitor())}</output>;
  }
  render(<Outside />);
  expect(screen.getByLabelText("monitor")).toHaveTextContent("null");
  cleanup();
  render(
    <RadioMonitorProvider programId="station">
      <RadioOutputPlayer listenerUrl="https://radio.example/stream" />
    </RadioMonitorProvider>,
  );
  expect(audios()).toHaveLength(2);
  await act(async () => {});
  expect(transport).not.toHaveBeenCalled();
});

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { apiUrl } from "../utils/apiBaseUrl";

export type RadioMonitorState = "stopped" | "buffering" | "playing";

/**
 * Listener-side audio only: it never issues a playout command. One instance owns one audio element
 * for one source (a Program's monitor grant, or an exact listener URL for fixtures).
 *
 * The monitor grant is prepared only while `prepare` is true and the audio is stopped, so a page
 * that shows no player never asks for one. Prepared before the click to keep play() inside
 * Safari's user gesture. Idle grants refresh from the producer's lifetime; active audio is never
 * replaced. Returning from a background tab refreshes an idle grant.
 */
export function useRadioListener({
  listenerUrl,
  programId,
  prepare = true,
}: {
  listenerUrl?: string;
  programId?: string;
  prepare?: boolean;
}) {
  const grantExpiresAt = useRef(0);
  const audioRef = useRef<HTMLAudioElement>(null);
  const request = useRef(0);
  const [state, setState] = useState<RadioMonitorState>("stopped");
  const [error, setError] = useState<string | null>(null);
  const [volume, setVolumeState] = useState(1);
  const [monitorUrl, setMonitorUrl] = useState<string | null>(null);
  const [preparing, setPreparing] = useState(false);
  const [retry, setRetry] = useState(0);

  useEffect(() => {
    if (!programId || !prepare || state !== "stopped") return;
    const abort = new AbortController();
    let timer: ReturnType<typeof setTimeout>;
    const prepareGrant = async () => {
      setPreparing(true);
      setMonitorUrl(null);
      try {
        const response = await fetch(
          apiUrl(`/radio/${encodeURIComponent(programId)}/monitor-ticket`),
          { method: "POST", signal: abort.signal },
        );
        if (!response.ok) throw new Error();
        const grant = await response.json();
        if (
          !Number.isFinite(grant.expiresInMs) ||
          grant.expiresInMs < 5_000 ||
          typeof grant.streamPath !== "string" ||
          !grant.streamPath.startsWith(
            `/radio/${encodeURIComponent(programId)}/monitor-audio?ticket=`,
          )
        )
          throw new Error();
        if (abort.signal.aborted) return;
        grantExpiresAt.current = Date.now() + grant.expiresInMs;
        setMonitorUrl(apiUrl(grant.streamPath));
        timer = setTimeout(() => void prepareGrant(), grant.expiresInMs - 5_000);
      } catch {
        if (!abort.signal.aborted)
          setError("The Program monitor could not connect. Retry connection.");
      } finally {
        if (!abort.signal.aborted) setPreparing(false);
      }
    };
    const refreshOnReturn = () => {
      if (document.visibilityState !== "visible") return;
      clearTimeout(timer);
      setRetry((value) => value + 1);
    };
    document.addEventListener("visibilitychange", refreshOnReturn);
    void prepareGrant();
    return () => {
      document.removeEventListener("visibilitychange", refreshOnReturn);
      abort.abort();
      clearTimeout(timer);
    };
  }, [programId, prepare, state, retry]);

  const stop = () => {
    request.current += 1;
    const audio = audioRef.current;
    if (audio) {
      audio.pause();
      audio.removeAttribute("src");
      audio.load();
    }
    setState("stopped");
  };
  useEffect(() => {
    const audio = audioRef.current;
    request.current += 1;
    setState("stopped");
    setError(null);
    return () => {
      request.current += 1;
      audio?.pause();
      audio?.removeAttribute("src");
      audio?.load();
    };
  }, [listenerUrl, programId]);

  const listen = async () => {
    const audio = audioRef.current;
    const source = programId ? monitorUrl : listenerUrl;
    if (!audio || !source) return;
    if (programId && Date.now() >= grantExpiresAt.current) {
      setMonitorUrl(null);
      setError(
        "Monitor connection expired. Preparing a new connection; press Listen when ready.",
      );
      setRetry((value) => value + 1);
      return;
    }
    const current = ++request.current;
    setError(null);
    setState("buffering");
    audio.src = source;
    audio.volume = volume;
    try {
      await audio.play();
      if (request.current === current) setState("playing");
    } catch {
      if (request.current !== current) return;
      stop();
      setError("Broadcast audio could not be played. Try listening again.");
    }
  };

  const setVolume = (next: number) => {
    setVolumeState(next);
    if (audioRef.current) audioRef.current.volume = next;
  };
  const retryConnection = () => {
    setError(null);
    setRetry((value) => value + 1);
  };

  const audioProps = {
    ref: audioRef,
    preload: "none" as const,
    onWaiting: () => {
      if (audioRef.current?.getAttribute("src")) setState("buffering");
    },
    onPlaying: () => {
      if (audioRef.current?.getAttribute("src")) setState("playing");
    },
    onEnded: stop,
    onError: () => {
      if (!audioRef.current?.getAttribute("src")) return;
      stop();
      setError("The listener stream is unavailable. Try listening again.");
    },
  };

  return {
    programId,
    state,
    error,
    volume,
    monitorUrl,
    preparing,
    audioProps,
    listen,
    stop,
    setVolume,
    retryConnection,
  };
}

export type RadioListener = ReturnType<typeof useRadioListener>;
type RadioMonitorValue = RadioListener & {
  /** A player view calls this while it is on screen; the grant is prepared only then. */
  attachPlayer: () => () => void;
};

const RadioMonitorContext = createContext<RadioMonitorValue | null>(null);

/**
 * The console's one listener audio element, mounted in the persistent layout so it keeps playing
 * while the operator moves between console pages. Changing program or leaving the layout (sign-out)
 * stops it: the element is released by the same cleanup as a station change.
 */
export function RadioMonitorProvider({
  programId,
  children,
}: {
  programId: string;
  children: ReactNode;
}) {
  const [players, setPlayers] = useState(0);
  const listener = useRadioListener({ programId, prepare: players > 0 });
  const attachPlayer = useMemo(
    () => () => {
      setPlayers((count) => count + 1);
      return () => setPlayers((count) => Math.max(0, count - 1));
    },
    [],
  );
  const value = { ...listener, attachPlayer };
  return (
    <RadioMonitorContext.Provider value={value}>
      <audio {...listener.audioProps} />
      {children}
    </RadioMonitorContext.Provider>
  );
}

/** The console's shared listener, or null outside the persistent layout (fixtures, tests). */
export function useRadioMonitor(): RadioMonitorValue | null {
  return useContext(RadioMonitorContext);
}

