    settings = {
      ...settings,
      timeOverrideEnabled: body.enabled,
      timeOverrideStartTime: body.startTime,
      timeOverrideStartedAt: body.enabled ? "2026-11-17T19:55:00.000Z" : null,
    };
    return json(
      body.startTime === "19:56"
        ? { ...settings, timeOverrideStartTime: null }
